import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'
import { DashboardSkeleton } from './DashboardSkeleton'

async function getDashboardData() {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

// Uncached, request-time data lives behind a Suspense boundary so it streams
// in while the rest of the page is served from the static shell.
async function DashboardData() {
  const data = await getDashboardData()

  return (
    <>
      <CardStats
        totalRevenue={data.totalRevenue}
        totalInvoices={data.totalInvoices}
      />
      <RevenueChart revenue={data.revenue} />
      <LatestInvoices invoices={data.invoices} />
    </>
  )
}

// The page itself does no data work, so it is fully prerendered into the
// static shell (the heading and the skeleton fallback ship instantly).
export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<DashboardSkeleton />}>
        <DashboardData />
      </Suspense>
    </main>
  )
}

